import torch
import torch.nn as nn

class DynamicModel(nn.Module):
    def __init__(self):
        super().__init__()
        self.fc = nn.Linear(5, 5)

    def forward(self, x):
        if x.sum() > 0:
            return self.fc(x)
        return x

model = DynamicModel().eval()
scripted_model = torch.jit.script(model)
output = scripted_model(torch.randn(1, 5))

